import{_ as t,o as i,c as o,a0 as n}from"./chunks/framework.DPd3ST4h.js";const p=JSON.parse('{"title":"GitHub composite action","description":"","frontmatter":{},"headers":[],"relativePath":"github-composite-action.md","filePath":"github-composite-action.md","lastUpdated":1792882158000}'),r={name:"github-composite-action.md"};function d(a,e,s,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="github-composite-action" tabindex="-1">GitHub composite action <a class="header-anchor" href="#github-composite-action" aria-label="Permalink to &quot;GitHub composite action&quot;">​</a></h1><p><code>github/action.yaml</code> is a composite action. It builds the review context bundle for a pull request&#39;s exact base and head commits and, when review inputs are supplied, builds bounded indexed context, runs the harness review, and uploads its output as artifacts.</p><h2 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h2><p>Inputs are fixed enums and data. No input accepts free-form review instructions.</p><table tabindex="0"><thead><tr><th>Input</th><th>Values</th><th>Notes</th></tr></thead><tbody><tr><td><code>backend</code></td><td><code>pi</code>, <code>opencode</code>, <code>echo</code></td><td>The review harness. <code>echo</code> is the deterministic test harness. Required together with <code>model-config</code> and <code>model-auth</code> to enable review execution.</td></tr><tr><td><code>model-config</code></td><td>JSON</td><td>Provider-neutral model configuration: <code>provider</code>, <code>endpoint</code>, <code>model</code>, and the optional <code>auth: &quot;none&quot;</code> credential-less profile for local model servers. See <a href="/projects/redline/runnable-review-configuration">runnable review configuration</a>.</td></tr><tr><td><code>model-auth</code></td><td>JSON secret</td><td>Provider-keyed credential map; bind to <code>secrets.MODEL_CREDENTIALS</code>. Only the selected provider&#39;s credential reaches the harness. Required whenever review execution is enabled — with a local model server declaring <code>auth: &quot;none&quot;</code> in <code>model-config</code>, pass a placeholder map: it satisfies the gate and is not consulted.</td></tr><tr><td><code>finding-scope</code></td><td><code>defects</code>, <code>defects-and-risks</code></td><td>Default <code>defects</code>.</td></tr><tr><td><code>timeout</code></td><td>duration</td><td>Per-file model deadline. Capped at 360m. Default <code>4m</code>.</td></tr><tr><td><code>run-timeout</code></td><td>duration</td><td>Whole-review deadline. Capped at 360m. Default <code>10m</code>; unstarted files become explicit omissions.</td></tr><tr><td><code>review-concurrency</code></td><td>1–8</td><td>Maximum simultaneous per-file model calls. Default <code>4</code>. Values outside the range or non-integers fail input validation.</td></tr><tr><td><code>runtime</code></td><td><code>node</code>, <code>bun</code></td><td>Trusted TypeScript source runtime. Default <code>node</code>. Node 24 and Bun 1.4.4 are pinned. This does not select harness or code-index provider runtimes.</td></tr><tr><td><code>verbosity</code></td><td><code>silent</code>, <code>progress</code>, <code>full-output</code></td><td>Live model stream in the run log: <code>silent</code> keeps per-file start/completion lines, <code>progress</code> adds bounded activity counts and diagnostics, and <code>full-output</code> prints readable stream text under a 32 KiB per-file cap. Default <code>progress</code>.</td></tr><tr><td><code>review-eligibility</code></td><td>policy JSON</td><td>Optional strict version-1 policy supplied by trusted workflow code. Empty loads <code>.redline/review-eligibility.json</code> directly from the exact base revision when present. See <a href="/projects/redline/review-eligibility">review eligibility</a>.</td></tr><tr><td><code>indexing</code></td><td><code>enabled</code>, <code>disabled</code></td><td>Default <code>enabled</code>. The action invokes its bundled <code>github/code-index</code> action at the same Redline commit. <code>disabled</code> preserves byte-identical file-only prompting. Missing, invalid, unsupported, or unavailable generated context keeps file-only review and records degraded coverage.</td></tr><tr><td><code>indexing-provider</code></td><td><code>cgc</code>, <code>gitnexus</code></td><td>Default <code>cgc</code>. Selects the action-owned pinned index provider. GitNexus is PolyForm Noncommercial 1.0.0 licensed; confirm suitability before selecting it. Provider-specific data never crosses the bounded artifact boundary.</td></tr><tr><td><code>artifact-name</code></td><td>name</td><td>Base name for artifacts. Default <code>redline-review-&lt;run id&gt;</code>.</td></tr><tr><td><code>artifact-retention-days</code></td><td>1–90</td><td>Default <code>45</code>.</td></tr><tr><td><code>github-token</code></td><td>secret</td><td>Fallback publication token (PAT), used when the App inputs are unset. An installation token generated outside the workflow is also accepted. Publication never uses the Actions <code>GITHUB_TOKEN</code>. Empty keeps artifact-only mode.</td></tr><tr><td><code>github-app-id</code></td><td>secret</td><td>Redline GitHub App id; with <code>github-app-key</code>, installation tokens are generated for the publication phases and preferred over the fallback.</td></tr><tr><td><code>github-app-key</code></td><td>secret</td><td>Redline GitHub App private key (PEM).</td></tr></tbody></table><p>Review execution is enabled only when <code>backend</code>, <code>model-config</code>, and <code>model-auth</code> are all supplied. Without them the action keeps the context-bundle-only behavior and does not index. Configured reviews index by default; set <code>indexing: disabled</code> for file-only review.</p><h2 id="publication" tabindex="-1">Publication <a class="header-anchor" href="#publication" aria-label="Permalink to &quot;Publication&quot;">​</a></h2><p>When <code>github-token</code> is supplied together with review execution, the action publishes the review to GitHub after writing the artifacts:</p><ul><li>One review per file with validated findings, bound to the reviewed head through <code>commit_id</code>, with one inline comment per finding. Publication runs as its own step with a freshly minted token after the review completes. Each comment carries the issue explanation, an apply-able <code>suggestion</code> block when the model proposed a concrete change, and the fix prompt for a coding agent.</li><li>One managed summary comment with run counts and per-file outcomes, updated in place on re-runs. A &quot;review in progress&quot; body is published when the run starts — the review runs one prompt per reviewed file and can take a while — and is replaced by the run summary (or the failure state) when the run completes. Parallel completion never changes manifest-order artifacts, synthesis, or publication. Publication context (repository, pull request, head) arrives together with the token; a partial selection fails validation.</li><li>Every managed object carries a machine-readable marker. Updating or creating one requires both the marker and the expected author, so the action never touches another author&#39;s content. The author is resolved from the token: a PAT through <code>GET /user</code>; a GitHub App installation token has no user behind <code>/user</code>, so the publisher learns its actor from the first object the token creates (authoritative response) and, across runs, recognizes its managed objects by marker plus the <code>## Redline review</code> heading — adopting the single marker-managed summary in place, failing closed on ambiguity, and never touching a marker comment without the managed heading. An explicit bot login (<code>botLogin</code>) remains an optional identity override.</li><li>Before publishing, the action re-reads the pull request head and aborts when the PR has moved past the reviewed commit.</li><li>Caps bound publication: at most 25 file reviews and 100 inline comments per run. Files and findings beyond the caps appear only in the summary.</li><li>Per-file publication failures never abort the run; failures are counted and reported in the summary. The action fails only when publication was requested and no requested file review succeeded.</li></ul><p>Re-runs on the same head are idempotent: an existing actor-owned review with the same marker is skipped, and the summary is updated in place. Reviews on earlier heads are outdated automatically by GitHub.</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h2><ol><li><strong>Validate action inputs</strong> — the event must be a <code>pull_request</code> with full base and head commit identifiers; the artifact settings and the all-or-nothing review-input rule are enforced.</li><li><strong>Set up and check trusted TypeScript</strong> — the selected Redline source runtime is installed (Node 24 by default or Bun 1.4.4), and the trusted source entrypoints are checked for presence. The review action does not run Corepack, install project dependencies, or type-check on the review critical path; strict <code>tsc --noEmit</code> remains a required CI gate. Pull request code is never installed, checked, or executed. The selector is not applied to harness commands. GitNexus separately installs its fixed Node 24 provider runtime.</li><li><strong>Generate Redline App token for review start</strong> — token 1, used by the announce and failure-notification steps; the publication token falls back to <code>github-token</code> when the App inputs are unset.</li><li><strong>Validate action inputs with trusted TypeScript</strong> — the review CLI runs <code>--validate-only</code> against the <code>REDLINE_*</code> environment contract; invalid optional inputs fail even in context-only mode.</li><li><strong>Restore validated per-file records</strong> — a PR-scoped GitHub Actions cache is restored into a dedicated directory. Availability is optional; missing or invalid cache data never changes correctness.</li><li><strong>Fetch pull request commits as data</strong> — base and head commits are fetched as Git objects and verified.</li><li><strong>Build bounded code index</strong> — for configured reviews with indexing enabled, the root action invokes <code>$/github/code-index</code>. GitHub resolves this self-repository reference at the root action&#39;s exact running commit. The child action exports the head as data, restores or builds the selected provider&#39;s bounded base-revision database, and writes provider-neutral <code>code-index/code-context.json</code>.</li><li><strong>Build review context bundle</strong> — the selected runtime executes <code>src/context-bundle.ts</code> directly to produce the manifest, diffs, base files, and a source-at-head export; a PR requirements file is folded in when present. Eligibility uses only strict trusted-workflow JSON or <code>.redline/review-eligibility.json</code> read from the exact base Git revision. Every exclusion carries a reason; pull-request head policy cannot suppress its own review.</li><li><strong>Upload review context artifact</strong> — <code>&lt;artifact-name&gt;-context</code> with the bounded <code>code-context.json</code> when generated, <code>source-at-head/</code>, and <code>review/</code>.</li><li><strong>Ensure harness binary</strong> — installs the selected harness&#39;s fixed npm package when review execution is enabled and the binary is not already present (<code>pi</code> or <code>opencode</code>; <code>echo</code> needs nothing). When Bun runs Redline source, a separate pinned Node 24 runtime is installed only for these Node-based harness commands. The runtime selector never changes the harness runtime. This is trusted workflow tooling, never pull request code.</li><li><strong>Announce review start</strong> — publishes the &quot;review in progress&quot; comment (continue-on-error; a failed notification never blocks the review). Token 1 covers this and the failure notification.</li><li><strong>Run harness review</strong> — token-free by design: the review process carries no publication credential. Before creating the worker queue, the CLI fingerprints every review-affecting input and restores only matching validated <code>clean</code> or <code>findings</code> records. Cached findings are remapped to the current base/head and revalidated against the current authoritative diff, source, and graph facts. Misses enter the bounded worker pool. Parallel runs schedule larger diffs first, isolate every Pi/OpenCode invocation, and restore manifest order before synthesis and publication. Each call receives the lesser of <code>timeout</code> and the remaining <code>run-timeout</code>; expiry produces explicit file omissions. <code>review-concurrency: 1</code> keeps manifest traversal. Candidate-verification benchmark mode remains serial while it uses the shared follow-up budget.</li><li><strong>Save validated per-file records</strong> — eligible records are written incrementally and the PR-scoped cache is saved with a unique run key under <code>always()</code>, so completed work can survive later failures or cancellation when GitHub permits the save step to run.</li><li><strong>Generate Redline App token for publication</strong> — token 2, minted after the review completes; it covers only the publication itself, so the token lifetime never bounds the review duration.</li><li><strong>Publish review</strong> — <code>--publish-only</code> re-reads the written records and summary from the output directory and publishes them (stale-head guard, run-to-head match, caps, per-file failure accounting).</li><li><strong>Notify review failure</strong> — when the harness review step failed, replaces the &quot;review in progress&quot; comment with the failure state (continue-on-error); prefers the fresh publication token when one was minted.</li><li><strong>Upload review output artifact</strong> — <code>&lt;artifact-name&gt;-reviews</code> with the per-file JSON and Markdown records and the run summary.</li></ol><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Pull request content is untrusted data. The harness receives it only inside a delimited context block with an explicit untrusted-data framing; it never alters the fixed policy. Review eligibility is selected only by trusted workflow input or the exact-base policy file, never by the pull-request head.</li><li>The harness runs with tools disabled and a constructed environment; no GitHub token or ambient credentials reach it. Every concurrent Pi/OpenCode call gets separate generated configuration, prompt, home, and state paths. The publication token is consumed only by the publication layer after the review artifacts are written.</li><li>Model output must validate against the authoritative diff — path, side, line, and byte-identical evidence — or the finding is rejected. Persisted reasons and raw model output are redacted against the selected credential before artifacts are written.</li><li>Restored review records are untrusted. Redline enforces cache version, namespace, file-name/path identity, SHA-256 integrity, schema, entry count, per-entry bytes, and total bytes. A semantic match includes the fixed policies and schemas, harness/model configuration, finding scope, timeout, diff, bounded revision-pinned source context, requirements, and source-resolved indexed context. Omissions and incomplete verification are never cached. A mismatch or validation failure becomes a normal model execution.</li><li>Indexed relationships only select candidates. Every injected span carries its path, line range, repository revision, provider/version, selection reason, and coverage status, and is re-resolved from the captured exact-head source with symlink and strict UTF-8 checks. Source files are capped at 2 MiB, selected content at 24 KiB per changed file and 48 KiB per run. Indexed context can never provide the published finding location.</li><li>Internal action composition uses GitHub.com&#39;s <code>$/</code> self-repository reference. GitHub Enterprise Server does not support this syntax; Forgejo and Gitea remain separate future entry points.</li><li>In context-only mode (review inputs empty) the action does not index and uploads only <code>&lt;artifact-name&gt;-context</code>; the <code>&lt;artifact-name&gt;-reviews</code> artifact is produced only when review execution is enabled.</li><li>Release tags contain the exact reviewed TypeScript source. The action executes only its trusted action revision; pull request source remains data and is never loaded as code.</li></ul><p>See <a href="/projects/redline/runnable-review-configuration">runnable review configuration</a> for the environment contract, <a href="/projects/redline/harness-executor">harness executor</a> for harness specifics, and <a href="/projects/redline/review-reporting">review output</a> for the record schema.</p>',15)])])}const m=t(r,[["render",d]]);export{p as __pageData,m as default};
